def solve(grid):
    n = len(grid)
    m = len(grid[0]) if n else 0

    # Identify distinct non‑zero values
    vals = set()
    for row in grid:
        for v in row:
            if v != 0:
                vals.add(v)

    if not vals:
        return grid

    # For each value record the set of (col‑row) differences and positions
    diffs_by_val = {}
    positions_by_val = {}
    for r in range(n):
        for c in range(m):
            v = grid[r][c]
            if v != 0:
                diffs_by_val.setdefault(v, set()).add(c - r)
                positions_by_val.setdefault(v, []).append((r, c))

    # The main value is the one whose cells share a single difference
    main_val = None
    filler_val = None
    for v, diff_set in diffs_by_val.items():
        if len(diff_set) == 1:
            main_val = v
        else:
            filler_val = v

    # Fallback if detection fails (e.g., only one non‑zero value)
    if main_val is None:
        main_val = max(positions_by_val, key=lambda v: len(positions_by_val[v]))
        filler_val = None

    main_diff = next(iter(diffs_by_val[main_val]))

    # Prepare output grid filled with zeros
    out = [[0] * m for _ in range(n)]

    # Place original diagonal of the main value
    for r in range(n):
        c = r + main_diff
        if 0 <= c < m:
            out[r][c] = main_val

    # If a filler value exists, determine the side and offset
    if filler_val is not None:
        filler_positions = positions_by_val[filler_val]

        # Find the earliest row containing filler
        min_row = min(r for r, _ in filler_positions)

        # Determine side (right if any filler cell is to the right of the diagonal at that row)
        diag_col_at_min = min_row + main_diff
        side = 0
        for r, c in filler_positions:
            if r == min_row:
                if c > diag_col_at_min:
                    side = 1
                    break
                elif c < diag_col_at_min:
                    side = -1
                    break
        if side == 0:               # should not happen, but guard
            side = 1

        # Compute the maximum distance from the diagonal on the chosen side
        max_dist = 0
        if side == 1:   # right side
            for r, c in filler_positions:
                if c > r + main_diff:
                    d = c - (r + main_diff)
                    if d > max_dist:
                        max_dist = d
        else:           # left side
            for r, c in filler_positions:
                if c < r + main_diff:
                    d = (r + main_diff) - c
                    if d > max_dist:
                        max_dist = d

        offset = max_dist + 2

        # Draw the second diagonal on the chosen side
        for r in range(n):
            new_c = r + main_diff + side * offset
            if 0 <= new_c < m:
                out[r][new_c] = main_val

    return out

